from itertools import permutations

class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        chars = sorted(set(''.join(words) + result))
        if len(chars) > 10:
            return False
        lead = {w[0] for w in words} | {result[0]}
        for perm in permutations(range(10), len(chars)):
            mp = dict(zip(chars, perm))
            if any(mp[c] == 0 for c in lead):
                continue
            total = sum(int(''.join(str(mp[c]) for c in w)) for w in words)
            target = int(''.join(str(mp[c]) for c in result))
            if total == target:
                return True
        return False

