class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        if max(len(w) for w in words) > len(result):
            return False
        cols = []
        for i in range(len(result)):
            cols.append([w[len(w) - 1 - i] for w in words if len(w) - 1 - i >= 0])
        lead = {w[0] for w in words} | {result[0]}
        mp = {}

        def solve(c, r, s, carry):
            if c == len(cols):
                return carry == 0
            if r == len(cols[c]):
                tot = s + carry
                d, nc = tot % 10, tot // 10
                ch = result[len(result) - 1 - c]
                if ch in mp:
                    return mp[ch] == d and solve(c + 1, 0, 0, nc)
                if d in mp.values() or (d == 0 and ch in lead):
                    return False
                mp[ch] = d
                if solve(c + 1, 0, 0, nc):
                    return True
                del mp[ch]
                return False
            ch = cols[c][r]
            if ch in mp:
                return solve(c, r + 1, s + mp[ch], carry)
            for d in range(10):
                if d in mp.values() or (d == 0 and ch in lead):
                    continue
                mp[ch] = d
                if solve(c, r + 1, s + d, carry):
                    return True
                del mp[ch]
            return False

        return solve(0, 0, 0, 0)

