class Solution {
    vector<vector<char>> cols;
    unordered_map<char,int> mp;
    bool used[10] = {};
    string result;
    unordered_set<char> lead;

    bool solve(int c, int r, long long s, int carry) {
        if (c == (int)cols.size()) return carry == 0;
        if (r == (int)cols[c].size()) {
            long long tot = s + carry;
            int d = tot % 10, nc = tot / 10;
            char ch = result[result.size() - 1 - c];
            auto it = mp.find(ch);
            if (it != mp.end()) return it->second == d && solve(c + 1, 0, 0, nc);
            if (used[d] || (d == 0 && lead.count(ch))) return false;
            mp[ch] = d; used[d] = true;
            if (solve(c + 1, 0, 0, nc)) return true;
            mp.erase(ch); used[d] = false;
            return false;
        }
        char ch = cols[c][r];
        auto it = mp.find(ch);
        if (it != mp.end()) return solve(c, r + 1, s + it->second, carry);
        for (int d = 0; d < 10; d++) {
            if (used[d] || (d == 0 && lead.count(ch))) continue;
            mp[ch] = d; used[d] = true;
            if (solve(c, r + 1, s + d, carry)) return true;
            mp.erase(ch); used[d] = false;
        }
        return false;
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        int mx = 0;
        for (auto& w : words) mx = max(mx, (int)w.size());
        if (mx > (int)result.size()) return false;
        this->result = result;
        for (auto& w : words) lead.insert(w[0]);
        lead.insert(result[0]);
        for (int i = 0; i < (int)result.size(); i++) {
            vector<char> col;
            for (auto& w : words)
                if ((int)w.size() - 1 - i >= 0) col.push_back(w[w.size() - 1 - i]);
            cols.push_back(col);
        }
        return solve(0, 0, 0, 0);
    }
};

