import java.util.*;

class Solution {
    List<List<Character>> cols = new ArrayList<>();
    Map<Character,Integer> mp = new HashMap<>();
    boolean[] used = new boolean[10];
    String result;
    Set<Character> lead = new HashSet<>();

    public boolean isSolvable(String[] words, String result) {
        int mx = 0;
        for (String w : words) mx = Math.max(mx, w.length());
        if (mx > result.length()) return false;
        this.result = result;
        for (String w : words) lead.add(w.charAt(0));
        lead.add(result.charAt(0));
        for (int i = 0; i < result.length(); i++) {
            List<Character> col = new ArrayList<>();
            for (String w : words)
                if (w.length() - 1 - i >= 0) col.add(w.charAt(w.length() - 1 - i));
            cols.add(col);
        }
        return solve(0, 0, 0L, 0);
    }

    boolean solve(int c, int r, long s, int carry) {
        if (c == cols.size()) return carry == 0;
        if (r == cols.get(c).size()) {
            long tot = s + carry;
            int d = (int)(tot % 10), nc = (int)(tot / 10);
            char ch = result.charAt(result.length() - 1 - c);
            if (mp.containsKey(ch)) return mp.get(ch) == d && solve(c + 1, 0, 0, nc);
            if (used[d] || (d == 0 && lead.contains(ch))) return false;
            mp.put(ch, d); used[d] = true;
            if (solve(c + 1, 0, 0, nc)) return true;
            mp.remove(ch); used[d] = false;
            return false;
        }
        char ch = cols.get(c).get(r);
        if (mp.containsKey(ch)) return solve(c, r + 1, s + mp.get(ch), carry);
        for (int d = 0; d < 10; d++) {
            if (used[d] || (d == 0 && lead.contains(ch))) continue;
            mp.put(ch, d); used[d] = true;
            if (solve(c, r + 1, s + d, carry)) return true;
            mp.remove(ch); used[d] = false;
        }
        return false;
    }
}

